import React, { useState } from 'react';
import { ToastContainer, toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import AutoSlideBanner from './components/AutoSlideBanner'; // আপনার কম্পোনেন্ট path adjust করো
import './RegisterForm.css'; // যদি CSS আলাদা রাখো

const API_BASE_URL = 'http://localhost:8080'; // Update with your Spring Boot API URL

export default function RegisterForm({ navigateToLogin }) {
  const [mobile, setMobile] = useState('');
  const [otp, setOtp] = useState('');
  const [password, setPassword] = useState('');
  const [referralCode, setReferralCode] = useState('');
  const [stage, setStage] = useState('send');
  const [loading, setLoading] = useState(false);

  const showToast = (type, message) => {
    toast[type](message, { position: "top-center", autoClose: 3000 });
  };

  const sendOtp = async () => {
    setLoading(true);
    try {
      const res = await fetch(`${API_BASE_URL}/api/otp/send`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ mobile }),
      });

      const data = await res.json().catch(() => ({}));

      if (!res.ok) {
        const errMsg = data.error || 'Something went wrong';
        showToast('error', errMsg);
        return;
      }

      showToast('success', 'OTP sent to your mobile');
      setStage('verify');
    } catch (err) {
      showToast('error', 'Network error, please try again');
    } finally {
      setLoading(false);
    }
  };

  const verifyOtpAndRegister = async () => {
    setLoading(true);
    try {
      const payload = { mobile, otp, password };
      if (referralCode && referralCode.trim() !== '') {
        payload.referralCode = referralCode.trim();
      }

      const res = await fetch(`${API_BASE_URL}/api/otp/verify`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });

      const data = await res.json().catch(() => ({}));

      if (!res.ok) {
        const errMsg = data.error || 'Something went wrong';
        showToast('error', errMsg);
        return;
      }

      showToast('success', 'Registration successful!');
      if (navigateToLogin) navigateToLogin();
    } catch (err) {
      showToast('error', 'Network error, please try again');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="register-form-wrapper">
      <AutoSlideBanner
        messages={[
          "Welcome to Ludo BD",
          "Finish Signup & Get up to Tk12",
          "Join 1.5 lac+ players"
        ]}
      />

      <h2>Finish Signup & Get up to <span className="highlight">Tk12</span></h2>
      <p>Enter 11 digit Mobile Number</p>

      <div className="input-group">
        <span className="country-code">+88 🇧🇩</span>
        <input
          type="tel"
          placeholder="Enter phone"
          value={mobile}
          onChange={(e) => setMobile(e.target.value)}
        />
      </div>

      {stage === 'verify' && (
        <>
          <input
            type="text"
            placeholder="Enter OTP"
            value={otp}
            onChange={(e) => setOtp(e.target.value)}
          />
          <input
            type="password"
            placeholder="Set Password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
          />
          <input
            type="text"
            placeholder="Referral Code (optional)"
            value={referralCode}
            onChange={(e) => setReferralCode(e.target.value)}
          />
        </>
      )}

      <p className="terms">
        I have read and agree to the <span className="terms-link">TERMS AND CONDITIONS</span>
      </p>

      <button
        onClick={stage === 'send' ? sendOtp : verifyOtpAndRegister}
        disabled={loading}
      >
        {loading ? 'Please wait...' : (stage === 'send' ? 'Next' : 'Verify & Register')}
      </button>

      <ToastContainer />
    </div>
  );
}
